('e:f136d64446ff6b44168a1313a674ec715c6166c88f0f937a7c9282325ae9a803','Vienna',2,'/viˈɛ.nə/','common',3.98,'capitalized','["proper noun"]','Ancient name of Vienne: a city in Isère, Auvergne-Rhône-Alpes, France','proper noun','Learned borrowing from Classical Latin Vienna, further etymology uncertain. Doublet of Vienne.',94,'80_120',1,0.68,68),
