('state of siege','state of siege',NULL,NULL,'rare',NULL,'multiword','["noun"]','An exceptional legal condition in which constitutional limits on the powers of the government are suspended, usually owing to military necessity and implying martial law.','noun','Calque of French état de siège, first codified in a 1791 law of the Constituent Assembly during the French Revolution as an aggravated condition of war justifying the subordination of the civilian government to military authorities. Extended to apply to internal rebellion by a French law of 1797; subsequently broadened again in 1849 to denote any political state of emergency.',378,'200plus',1,0.7,296),
('rhabdo-','rhabdo-',NULL,NULL,'scarce',1.42,'hyphenated','["prefix"]','rod, rod-like','prefix','Borrowed from Ancient Greek ῥάβδος (rhábdos, “rod, wand”).',58,'40_80',1,0.49,297),
('e:101d114d79730abd73d720eba67d3318b2272686797028a3566e224e05eb6438','fry',1,'/fɹaɪ/','common',4.19,'plain','["noun", "verb"]','A long, thin fried piece of cut potato.','noun','Inherited from Middle English fryen, borrowed from Old French frire, from Latin frīgō. Cognate with Ancient Greek φρύγω (phrúgō, “to roast, bake”), Sanskrit भृज्जति (bhṛjjati, “to roast, grill, fry”). Replaced native Middle English hirsten, from Old English hierstan (“to fry”). Related to bhurji, bhujia (“fried Indian snacks”).',329,'200plus',1,0.8,298),
('Aš','Aš',NULL,NULL,'rare',NULL,'capitalized,nonascii','["proper noun"]','A city in the western Czech Republic.','proper noun','From Czech Aš.',14,'lt40',1,0.35,299),
('Yeh-ch''eng','Yeh-ch''eng',NULL,NULL,'marginal',NULL,'capitalized,hyphenated,apostrophe,pointer_only','["proper noun"]','Alternative form of Yecheng (Kargilik)','proper noun','From Mandarin 葉城 /叶城 (Yèchéng), Wade–Giles romanization: Yeh⁴-chʻêng².',70,'40_80',1,0.4,300);
